parameters.jsCode:
const normalizarTexto = (valor) =>
  String(valor || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim();

const mensajeOriginal =
  String($json.message || "");

const texto =
  normalizarTexto(mensajeOriginal);

// --------------------------------------------------
// Señales de agenda o reserva
// --------------------------------------------------

const patronesAgendaGenerica = [
  /\bagendar\b/,
  /\breservar\b/,
  /\bpedir\s+(?:una\s+)?hora\b/,
  /\btomar\s+(?:una\s+)?hora\b/,
  /\bsacar\s+(?:una\s+)?hora\b/,
  /\bnecesito\s+(?:una\s+)?hora\b/,
  /\bquiero\s+(?:una\s+)?hora\b/,
  /\bnecesito\s+(?:una\s+)?cita\b/,
  /\bquiero\s+(?:una\s+)?cita\b/
];

const solicitaAgendaGenerica =
  patronesAgendaGenerica.some(
    (patron) =>
      patron.test(texto)
  );

// --------------------------------------------------
// Señales de peluquería
// --------------------------------------------------

const patronesPeluqueria = [
  /\bpeluqueria\b/,
  /\bgrooming\b/,
  /\bbano\b/,
  /\blavado\b/,
  /\bcorte\s+de\s+pelo\b/,
  /\bbano\s+y\s+corte\b/,
  /\blavado\s+y\s+corte\b/,
  /\bservicio\s+de\s+corte\b/
];

const mencionaPeluqueria =
  patronesPeluqueria.some(
    (patron) =>
      patron.test(texto)
  );

const solicitaCorteDirecto =
  /\b(?:quiero|necesito|quisiera|solicito)\s+(?:un\s+|el\s+)?corte\b/.test(
    texto
  );

const solicitaServicioPeluqueriaDirecto =
  /\b(?:quiero|necesito|quisiera|solicito)\s+(?:un\s+|una\s+|el\s+|la\s+)?(?:bano|lavado|peluqueria|grooming|corte\s+de\s+pelo|bano\s+y\s+corte|lavado\s+y\s+corte)\b/.test(
    texto
  ) ||
  solicitaCorteDirecto;

const iniciaSolicitudPeluqueria =
  solicitaServicioPeluqueriaDirecto ||
  (
    mencionaPeluqueria &&
    solicitaAgendaGenerica
  );

// --------------------------------------------------
// Señales de agenda médica
// --------------------------------------------------

const patronesMedicos = [
  /\bconsulta\b/,
  /\bconsulta\s+general\b/,
  /\bveterinaria\b/,
  /\bveterinario\b/,
  /\bvacuna\b/,
  /\bvacunacion\b/,
  /\bcontrol\s+veterinario\b/,
  /\bagenda\s+medica\b/,
  /\bcita\s+veterinaria\b/
];

const mencionaAgendaMedica =
  patronesMedicos.some(
    (patron) =>
      patron.test(texto)
  );

const iniciaSolicitudMedicaExplicita =
  mencionaAgendaMedica &&
  (
    solicitaAgendaGenerica ||
    /\b(?:quiero|necesito|quisiera|solicito)\s+(?:una\s+)?consulta\b/.test(
      texto
    )
  );

// --------------------------------------------------
// Elección explícita después de una aclaración
// --------------------------------------------------

const eligeAgendaMedica =
  /\b(?:prefiero|elijo)\s+(?:continuar\s+con\s+)?(?:la\s+)?(?:consulta(?:\s+veterinaria)?|agenda\s+medica|cita\s+veterinaria)\b/.test(
    texto
  ) ||
  /\b(?:continuar|seguir)\s+con\s+(?:la\s+)?(?:consulta(?:\s+veterinaria)?|agenda\s+medica|cita\s+veterinaria)\b/.test(
    texto
  );

const eligePeluqueria =
  /\b(?:prefiero|elijo)\s+(?:continuar\s+con\s+)?(?:la\s+)?(?:agenda\s+de\s+peluqueria|peluqueria|bano\s+y\s+corte|lavado\s+y\s+corte|bano|lavado|corte)\b/.test(
    texto
  ) ||
  /\b(?:continuar|seguir)\s+con\s+(?:la\s+)?(?:agenda\s+de\s+peluqueria|peluqueria|bano\s+y\s+corte|lavado\s+y\s+corte|bano|lavado|corte)\b/.test(
    texto
  );

// --------------------------------------------------
// Consultas públicas informativas
// --------------------------------------------------

const patronesConsultaInformativa = [
  /\b(?:cuanto\s+cuesta|cuanto\s+sale|precio|valor)\b/,
  /\b(?:horario\s+de\s+atencion|a\s+que\s+hora\s+abren|a\s+que\s+hora\s+cierran)\b/,
  /\b(?:que\s+servicios|cuales\s+servicios|que\s+ofrecen)\b/,
  /\b(?:medios?\s+de\s+pago|formas?\s+de\s+pago|aceptan\s+tarjeta)\b/,
  /\b(?:quiero\s+saber|necesito\s+saber|quisiera\s+saber|informame|cuentame)\b/
];

const parecePregunta =
  /[¿?]/.test(mensajeOriginal) ||
  /^(?:que|cual|cuales|cuanto|como|donde|cuando|tienen|ofrecen|aceptan|atienden|hay)\b/.test(
    texto
  );

const esConsultaInformativaComercial =
  !solicitaAgendaGenerica &&
  !iniciaSolicitudPeluqueria &&
  !iniciaSolicitudMedicaExplicita &&
  !eligeAgendaMedica &&
  !eligePeluqueria &&
  (
    parecePregunta ||
    patronesConsultaInformativa.some(
      (patron) =>
        patron.test(texto)
    )
  );

// --------------------------------------------------
// Estados abiertos de ambas agendas
// --------------------------------------------------

const estadosFinalizados = [
  "confirmada",
  "cancelada",
  "cerrada"
];

const estadoMedico =
  String(
    $json.estadoAgenda?.estado_agenda || ""
  )
    .trim()
    .toLowerCase();

const teniaAgendaMedicaAbierta =
  Boolean($json.existeEstado) &&
  $json.iniciarNuevaAgenda !== true &&
  !estadosFinalizados.includes(
    estadoMedico
  );

const estadoPeluqueria =
  String(
    $json.estadoPeluqueria?.estado_peluqueria || ""
  )
    .trim()
    .toLowerCase();

const teniaPeluqueriaAbierta =
  Boolean(
    $json.existeEstadoPeluqueria
  ) &&
  $json.iniciarNuevaPeluqueria !== true &&
  !estadosFinalizados.includes(
    estadoPeluqueria
  );

const ambasAgendasAbiertas =
  teniaAgendaMedicaAbierta &&
  teniaPeluqueriaAbierta;

// --------------------------------------------------
// Casos que necesitan aclaración
// --------------------------------------------------

const agendaSinTipoDefinido =
  solicitaAgendaGenerica &&
  !mencionaPeluqueria &&
  !mencionaAgendaMedica &&
  !eligeAgendaMedica &&
  !eligePeluqueria &&
  !teniaAgendaMedicaAbierta &&
  !teniaPeluqueriaAbierta;

const intentaCambiarAMedica =
  teniaPeluqueriaAbierta &&
  !teniaAgendaMedicaAbierta &&
  iniciaSolicitudMedicaExplicita &&
  !eligeAgendaMedica;

const intentaCambiarAPeluqueria =
  teniaAgendaMedicaAbierta &&
  !teniaPeluqueriaAbierta &&
  iniciaSolicitudPeluqueria &&
  !eligePeluqueria;

const mensajeAmbiguoConAmbasAbiertas =
  ambasAgendasAbiertas &&
  !iniciaSolicitudPeluqueria &&
  !iniciaSolicitudMedicaExplicita &&
  !eligeAgendaMedica &&
  !eligePeluqueria &&
  !esConsultaInformativaComercial;

const requiereAclararAgenda =
  agendaSinTipoDefinido ||
  intentaCambiarAMedica ||
  intentaCambiarAPeluqueria ||
  mensajeAmbiguoConAmbasAbiertas;

let motivoAclaracionAgenda = "";

if (agendaSinTipoDefinido) {
  motivoAclaracionAgenda =
    "agenda_sin_tipo";
} else if (intentaCambiarAMedica) {
  motivoAclaracionAgenda =
    "peluqueria_abierta_intenta_medica";
} else if (intentaCambiarAPeluqueria) {
  motivoAclaracionAgenda =
    "medica_abierta_intenta_peluqueria";
} else if (mensajeAmbiguoConAmbasAbiertas) {
  motivoAclaracionAgenda =
    "ambas_agendas_abiertas";
}

// --------------------------------------------------
// Continuidad de peluquería
// --------------------------------------------------

const tienePeluqueriaEnCurso =
  teniaPeluqueriaAbierta &&
  !esConsultaInformativaComercial &&
  !iniciaSolicitudMedicaExplicita &&
  !eligeAgendaMedica &&
  !requiereAclararAgenda;

const esSolicitudPeluqueria =
  !requiereAclararAgenda &&
  (
    iniciaSolicitudPeluqueria ||
    eligePeluqueria ||
    tienePeluqueriaEnCurso
  );

// --------------------------------------------------
// Selección o continuidad médica
// --------------------------------------------------

const forzarAgendaMedica =
  !requiereAclararAgenda &&
  eligeAgendaMedica;

// --------------------------------------------------
// Resultado
// --------------------------------------------------

return {
  json: {
    ...$json,

    textoComercialNormalizado:
      texto,

    mencionaPeluqueria,
    mencionaAgendaMedica,

    solicitaAgendaGenerica,

    iniciaSolicitudPeluqueria,
    iniciaSolicitudMedicaExplicita,

    eligeAgendaMedica,
    eligePeluqueria,

    esConsultaInformativaComercial,

    teniaAgendaMedicaAbierta,
    teniaPeluqueriaAbierta,
    ambasAgendasAbiertas,

    agendaSinTipoDefinido,
    requiereAclararAgenda,
    motivoAclaracionAgenda,

    tienePeluqueriaEnCurso,
    esSolicitudPeluqueria,

    forzarAgendaMedica
  }
};

