parameters.jsCode:
const DateTime =
  $now.constructor;

const config =
  $json.peluqueriaConfig || {};

const datosReserva =
  $json.datosReservaPeluqueria || {};

const resolucion =
  $json.resolucionServicioPeluqueria || {};

const zonaHoraria =
  String(
    config.zona_horaria ||
    "America/Santiago"
  ).trim();

const startTime =
  String(
    $json.startTime ||
    $json.estadoPeluqueria?.start_time ||
    ""
  ).trim();

const endTime =
  String(
    $json.endTime ||
    $json.estadoPeluqueria?.end_time ||
    ""
  ).trim();

const duracionMinutos =
  Number(
    datosReserva.duracion_minutos ||
    resolucion.duracion_minutos ||
    $json.estadoPeluqueria?.duracion_minutos ||
    0
  );

const intervaloInicioMinutos =
  Number(
    datosReserva.intervalo_inicio_minutos ||
    resolucion.intervalo_inicio_minutos ||
    config.intervalo_inicio_predeterminado_minutos ||
    config.intervalo_inicio_minutos_default ||
    config.intervalo_inicio_minutos ||
    30
  );

const inicio =
  startTime
    ? DateTime.fromISO(
        startTime,
        {
          zone: zonaHoraria
        }
      )
    : null;

const fin =
  endTime
    ? DateTime.fromISO(
        endTime,
        {
          zone: zonaHoraria
        }
      )
    : null;

const ahora =
  $now.setZone(
    zonaHoraria
  );

// --------------------------------------------------
// Normalización general
// --------------------------------------------------

const normalizarTexto = (valor) =>
  String(valor || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(
      /[\u0300-\u036f]/g,
      ""
    )
    .trim();

const nombresDias = {
  1: "lunes",
  2: "martes",
  3: "miercoles",
  4: "jueves",
  5: "viernes",
  6: "sabado",
  7: "domingo"
};

const nombreDia =
  inicio?.isValid
    ? nombresDias[inicio.weekday]
    : "";

const horariosPorDia =
  config.horarios_por_dia ||
  config.horarios ||
  config.schedule ||
  {};

const buscarConfiguracionDia = () => {
  if (
    !horariosPorDia ||
    typeof horariosPorDia !== "object"
  ) {
    return null;
  }

  for (
    const [clave, valor]
    of Object.entries(
      horariosPorDia
    )
  ) {
    if (
      normalizarTexto(clave) ===
      nombreDia
    ) {
      return valor;
    }
  }

  return null;
};

const configuracionDia =
  buscarConfiguracionDia();

// --------------------------------------------------
// Normalizar ventanas de atención
// --------------------------------------------------

const normalizarVentanas = (
  valor
) => {
  if (
    valor === null ||
    valor === undefined ||
    valor === false
  ) {
    return [];
  }

  if (typeof valor === "string") {
    const coincidencia =
      valor.match(
        /(\d{1,2}:\d{2})\s*[-–]\s*(\d{1,2}:\d{2})/
      );

    if (!coincidencia) {
      return [];
    }

    return [
      {
        apertura:
          coincidencia[1],

        cierre:
          coincidencia[2]
      }
    ];
  }

  if (Array.isArray(valor)) {
    return valor.flatMap(
      (item) =>
        normalizarVentanas(item)
    );
  }

  if (typeof valor === "object") {
    const activo =
      valor.activo ??
      valor.active ??
      valor.habilitado ??
      true;

    if (activo === false) {
      return [];
    }

    const apertura =
      valor.apertura ||
      valor.inicio ||
      valor.desde ||
      valor.start ||
      valor.hora_inicio ||
      "";

    const cierre =
      valor.cierre ||
      valor.fin ||
      valor.hasta ||
      valor.end ||
      valor.hora_fin ||
      "";

    if (
      apertura &&
      cierre
    ) {
      return [
        {
          apertura:
            String(
              apertura
            ).trim(),

          cierre:
            String(
              cierre
            ).trim()
        }
      ];
    }

    return normalizarVentanas(
      valor.ventanas ||
      valor.bloques ||
      valor.rangos ||
      valor.windows ||
      []
    );
  }

  return [];
};

const ventanasDia =
  normalizarVentanas(
    configuracionDia
  );

// --------------------------------------------------
// Fechas bloqueadas
// --------------------------------------------------

const fechasBloqueadasConfiguradas =
  config.fechas_bloqueadas ||
  config.blocked_dates ||
  [];

const fechasBloqueadas =
  Array.isArray(
    fechasBloqueadasConfiguradas
  )
    ? fechasBloqueadasConfiguradas
        .map((item) => {
          if (
            typeof item === "string"
          ) {
            return item.trim();
          }

          if (
            item &&
            typeof item === "object"
          ) {
            return String(
              item.fecha ||
              item.date ||
              ""
            ).trim();
          }

          return "";
        })
        .filter(Boolean)
    : [];

const fechaSolicitada =
  inicio?.isValid
    ? inicio.toISODate()
    : "";

const fechaBloqueada =
  Boolean(
    fechaSolicitada &&
    fechasBloqueadas.includes(
      fechaSolicitada
    )
  );

// --------------------------------------------------
// Conversión de horas
// --------------------------------------------------

const convertirHoraAMinutos = (
  valor
) => {
  const coincidencia =
    String(valor || "")
      .trim()
      .match(
        /^(\d{1,2}):(\d{2})$/
      );

  if (!coincidencia) {
    return null;
  }

  const horas =
    Number(coincidencia[1]);

  const minutos =
    Number(coincidencia[2]);

  if (
    horas < 0 ||
    horas > 23 ||
    minutos < 0 ||
    minutos > 59
  ) {
    return null;
  }

  return (
    horas * 60 +
    minutos
  );
};

const inicioMinutos =
  inicio?.isValid
    ? (
        inicio.hour * 60 +
        inicio.minute
      )
    : null;

const finMinutos =
  fin?.isValid
    ? (
        fin.hour * 60 +
        fin.minute
      )
    : null;

// --------------------------------------------------
// Validación de jornada
// --------------------------------------------------

let dentroDeJornada = false;
let cumpleIntervalo = false;
let terminaDentroDeJornada = false;
let ventanaAplicable = null;

if (
  inicio?.isValid &&
  fin?.isValid &&
  inicio.toISODate() ===
    fin.toISODate()
) {
  for (
    const ventana
    of ventanasDia
  ) {
    const apertura =
      convertirHoraAMinutos(
        ventana.apertura
      );

    const cierre =
      convertirHoraAMinutos(
        ventana.cierre
      );

    if (
      apertura === null ||
      cierre === null
    ) {
      continue;
    }

    const iniciaDentro =
      inicioMinutos >= apertura &&
      inicioMinutos < cierre;

    const terminaDentro =
      finMinutos <= cierre &&
      finMinutos > apertura;

    const intervaloValido =
      intervaloInicioMinutos > 0 &&
      (
        (
          inicioMinutos -
          apertura
        ) %
        intervaloInicioMinutos
      ) === 0;

    if (iniciaDentro) {
      dentroDeJornada = true;

      cumpleIntervalo =
        intervaloValido;

      terminaDentroDeJornada =
        terminaDentro;

      ventanaAplicable = {
        apertura:
          ventana.apertura,

        cierre:
          ventana.cierre
      };

      break;
    }
  }
}

// --------------------------------------------------
// Coherencia de duración
// --------------------------------------------------

const duracionCalculada =
  inicio?.isValid &&
  fin?.isValid
    ? Math.round(
        fin.diff(
          inicio,
          "minutes"
        ).minutes
      )
    : 0;

const duracionCoherente =
  duracionMinutos > 0 &&
  duracionCalculada ===
    duracionMinutos;

// --------------------------------------------------
// Resultado de validación
// --------------------------------------------------

const motivos = [];

if (
  !inicio?.isValid ||
  !fin?.isValid
) {
  motivos.push(
    "fecha_hora_invalida"
  );
}

if (
  inicio?.isValid &&
  inicio <= ahora
) {
  motivos.push(
    "fecha_hora_pasada"
  );
}

if (fechaBloqueada) {
  motivos.push(
    "fecha_bloqueada"
  );
}

if (
  inicio?.isValid &&
  ventanasDia.length === 0
) {
  motivos.push(
    "dia_sin_atencion"
  );
}

if (
  ventanasDia.length > 0 &&
  !dentroDeJornada
) {
  motivos.push(
    "fuera_de_horario"
  );
}

if (
  dentroDeJornada &&
  !cumpleIntervalo
) {
  motivos.push(
    "intervalo_no_permitido"
  );
}

if (
  dentroDeJornada &&
  !terminaDentroDeJornada
) {
  motivos.push(
    "termina_fuera_de_jornada"
  );
}

if (
  duracionMinutos <= 0
) {
  motivos.push(
    "duracion_invalida"
  );
} else if (
  inicio?.isValid &&
  fin?.isValid &&
  !duracionCoherente
) {
  motivos.push(
    "duracion_inconsistente"
  );
}

const esValido =
  motivos.length === 0;

return {
  json: {
    ...$json,

    validacionHorarioPeluqueria: {
      es_valido:
        esValido,

      motivos,

      motivo_principal:
        motivos[0] || "",

      fecha_solicitada:
        fechaSolicitada,

      dia_semana:
        nombreDia,

      duracion_minutos:
        duracionMinutos,

      duracion_calculada:
        duracionCalculada,

      duracion_coherente:
        duracionCoherente,

      intervalo_inicio_minutos:
        intervaloInicioMinutos,

      fecha_bloqueada:
        fechaBloqueada,

      dentro_de_jornada:
        dentroDeJornada,

      cumple_intervalo:
        cumpleIntervalo,

      termina_dentro_de_jornada:
        terminaDentroDeJornada,

      ventana_aplicable:
        ventanaAplicable,

      ventanas_disponibles:
        ventanasDia
    }
  }
};

const estadoAnterior =
  $json.estadoPeluqueria || {};

const datosReserva =
  $json.datosReservaPeluqueria || {};

const resolucion =
  $json.resolucionServicioPeluqueria || {};

const validacion =
  $json.validacionHorarioPeluqueria || {};

const clinicId =
  String(
    $json.clinic_id ||
    estadoAnterior.clinic_id ||
    ""
  ).trim();

const sessionId =
  String(
    $json.session_id ||
    estadoAnterior.session_id ||
    ""
  ).trim();

const sessionKey =
  String(
    $json.session_key ||
    estadoAnterior.session_key ||
    (
      clinicId && sessionId
        ? `${clinicId}::${sessionId}`
        : ""
    )
  ).trim();

const normalizarOpcionesJson = (
  valor
) => {
  if (Array.isArray(valor)) {
    return JSON.stringify(valor);
  }

  const texto =
    String(valor || "").trim();

  return texto || "[]";
};

const estadoPeluqueriaGuardar = {
  session_key:
    sessionKey,

  clinic_id:
    clinicId,

  session_id:
    sessionId,

  estado_peluqueria:
    "esperando_horario_valido",

  service_id:
    String(
      datosReserva.service_id ||
      resolucion.service_id ||
      estadoAnterior.service_id ||
      ""
    ).trim(),

  nombre_servicio:
    String(
      datosReserva.nombre_servicio ||
      resolucion.nombre_servicio ||
      estadoAnterior.nombre_servicio ||
      ""
    ).trim(),

  duracion_minutos:
    Number(
      datosReserva.duracion_minutos ||
      resolucion.duracion_minutos ||
      estadoAnterior.duracion_minutos ||
      0
    ),

  nombre_tutor:
    String(
      datosReserva.nombre_tutor ||
      estadoAnterior.nombre_tutor ||
      ""
    ).trim(),

  telefono:
    String(
      datosReserva.telefono ||
      estadoAnterior.telefono ||
      ""
    ).trim(),

  nombre_mascota:
    String(
      datosReserva.nombre_mascota ||
      estadoAnterior.nombre_mascota ||
      ""
    ).trim(),

  especie:
    String(
      datosReserva.especie ||
      resolucion.especie ||
      estadoAnterior.especie ||
      "perro"
    ).trim(),

  tamano:
    String(
      datosReserva.tamano ||
      resolucion.tamano ||
      estadoAnterior.tamano ||
      ""
    ).trim(),

  tipo_pelaje:
    String(
      datosReserva.tipo_pelaje ||
      resolucion.tipo_pelaje ||
      estadoAnterior.tipo_pelaje ||
      ""
    ).trim(),

  fecha_pendiente:
    String(
      $json.interpretacionHorarioPeluqueria
        ?.fecha_detectada ||
      estadoAnterior.fecha_pendiente ||
      ""
    ).trim(),

  hora_pendiente:
    String(
      $json.interpretacionHorarioPeluqueria
        ?.hora_detectada ||
      estadoAnterior.hora_pendiente ||
      ""
    ).trim(),

  start_time:
    String(
      $json.startTime ||
      estadoAnterior.start_time ||
      ""
    ).trim(),

  end_time:
    String(
      $json.endTime ||
      estadoAnterior.end_time ||
      ""
    ).trim(),

  opciones_json:
    normalizarOpcionesJson(
      estadoAnterior.opciones_json
    ),

  updated_at:
    new Date().toISOString()
};

return {
  json: {
    ...$json,

    motivoHorarioPeluqueriaInvalido:
      String(
        validacion.motivo_principal ||
        ""
      ).trim(),

    estadoPeluqueriaGuardar
  }
};

