={{ (() => {
  const origen =
    $("Preparar estado horario peluquería inválido")
      .first()
      .json;

  const validacion =
    origen.validacionHorarioPeluqueria || {};

  const motivo =
    String(
      validacion.motivo_principal || ""
    ).trim();

  const dia =
    String(
      validacion.dia_semana || ""
    ).trim();

  const ventanas =
    Array.isArray(
      validacion.ventanas_disponibles
    )
      ? validacion.ventanas_disponibles
      : [];

  const horarioDia =
    ventanas
      .map(
        (ventana) =>
          `${ventana.inicio} a ${ventana.fin}`
      )
      .join(" y ");

  if (
    motivo === "fecha_hora_pasada"
  ) {
    return (
      "Ese horario ya pasó. Indica una fecha y una hora futuras para la reserva de peluquería."
    );
  }

  if (
    motivo === "fecha_bloqueada"
  ) {
    return (
      "La clínica no tiene atención de peluquería en esa fecha. Indica otra fecha y hora."
    );
  }

  if (
    motivo === "dia_sin_atencion"
  ) {
    return (
      "No hay atención de peluquería ese día. Indica otra fecha y hora."
    );
  }

  if (
    motivo === "intervalo_no_permitido"
  ) {
    return (
      "Los horarios de peluquería comienzan en intervalos de " +
      validacion.intervalo_inicio_minutos +
      " minutos. Indica otro horario."
    );
  }

  if (
    motivo === "termina_fuera_de_jornada"
  ) {
    return (
      "Ese servicio no alcanza a finalizar antes del cierre. Indica un horario más temprano."
    );
  }

  if (
    motivo === "fuera_de_horario"
  ) {
    return horarioDia
      ? (
          "Ese horario está fuera de la jornada de peluquería del " +
          dia +
          ". Ese día se atiende de " +
          horarioDia +
          "."
        )
      : (
          "Ese horario está fuera de la jornada de peluquería. Indica otra fecha y hora."
        );
  }

  return (
    "Ese horario no es válido para la reserva de peluquería. Indica otra fecha y hora."
  );
})() }}

