const solicitud =
  $("Validar horario solicitado peluquería")
    .first()
    .json;

return {
  json: {
    ...solicitud,

    disponibilidadPeluqueria: {
      available:
        $json.available === true
    }
  }
};

const DateTime =
  $now.constructor;

const config =
  $json.peluqueriaConfig || {};

const datosReserva =
  $json.datosReservaPeluqueria || {};

const resolucion =
  $json.resolucionServicioPeluqueria || {};

const estadoAnterior =
  $json.estadoPeluqueria || {};

const zonaHoraria =
  String(
    config.zona_horaria ||
    "America/Santiago"
  ).trim();

const diasABuscar =
  Math.max(
    Number(
      config.dias_a_buscar ||
      7
    ),
    1
  );

const duracionMinutos =
  Number(
    datosReserva.duracion_minutos ||
    resolucion.duracion_minutos ||
    estadoAnterior.duracion_minutos ||
    0
  );

const intervaloInicioMinutos =
  Number(
    datosReserva.intervalo_inicio_minutos ||
    resolucion.intervalo_inicio_minutos ||
    config.intervalo_inicio_minutos_default ||
    config.intervalo_inicio_minutos ||
    30
  );

const cantidadAlternativas =
  Math.max(
    Number(
      config.cantidad_alternativas ||
      config.max_alternativas ||
      3
    ),
    1
  );

const ahora =
  $now.setZone(
    zonaHoraria
  );

const inicioSolicitadoTexto =
  String(
    $json.startTime ||
    estadoAnterior.start_time ||
    ""
  ).trim();

const inicioSolicitado =
  inicioSolicitadoTexto
    ? DateTime.fromISO(
        inicioSolicitadoTexto,
        {
          zone: zonaHoraria
        }
      )
    : null;

const inicioBusqueda =
  ahora.startOf(
    "minute"
  );

const finBusqueda =
  ahora
    .startOf("day")
    .plus({
      days: diasABuscar
    });

return {
  json: {
    ...$json,

    busquedaAlternativasPeluqueria: {
      zona_horaria:
        zonaHoraria,

      dias_a_buscar:
        diasABuscar,

      cantidad_alternativas:
        cantidadAlternativas,

      duracion_minutos:
        duracionMinutos,

      intervalo_inicio_minutos:
        intervaloInicioMinutos,

      inicio_solicitado:
        inicioSolicitado?.isValid
          ? inicioSolicitado.toISO()
          : "",

      inicio_busqueda:
        inicioBusqueda.toISO(),

      fin_busqueda:
        finBusqueda.toISO()
    }
  }
};

const DateTime =
  $now.constructor;

const origen =
  $("Preparar búsqueda alternativas peluquería")
    .first()
    .json;

const busqueda =
  origen.busquedaAlternativasPeluqueria ||
  {};

const zonaHoraria =
  String(
    busqueda.zona_horaria ||
    "America/Santiago"
  ).trim();

const items =
  $input.all();

const esItemConError = (
  item
) => {
  const json =
    item?.json || {};

  return Boolean(
    json.error ||
    json.errorMessage ||
    json.executionError ||
    json.name === "NodeApiError" ||
    json.name === "NodeOperationError"
  );
};

const errorConsulta =
  items.some(
    esItemConError
  );

const convertirFecha = (
  valor
) => {
  const texto =
    String(valor || "").trim();

  if (!texto) {
    return "";
  }

  const esSoloFecha =
    /^\d{4}-\d{2}-\d{2}$/.test(
      texto
    );

  const fecha =
    esSoloFecha
      ? DateTime.fromISO(
          texto,
          {
            zone: zonaHoraria
          }
        ).startOf("day")
      : DateTime.fromISO(
          texto,
          {
            zone: zonaHoraria
          }
        );

  return fecha.isValid
    ? fecha.toISO()
    : "";
};

const eventosOcupados = [];

for (const item of items) {
  if (
    esItemConError(item)
  ) {
    continue;
  }

  const evento =
    item.json || {};

  if (
    evento.status === "cancelled"
  ) {
    continue;
  }

  const inicio =
    convertirFecha(
      evento.start?.dateTime ||
      evento.start?.date ||
      evento.startTime ||
      evento.start_time ||
      evento.inicio ||
      ""
    );

  const fin =
    convertirFecha(
      evento.end?.dateTime ||
      evento.end?.date ||
      evento.endTime ||
      evento.end_time ||
      evento.fin ||
      ""
    );

  if (
    inicio &&
    fin
  ) {
    eventosOcupados.push({
      inicio,
      fin
    });
  }
}

return [
  {
    json: {
      ...origen,

      consultaEventosPeluqueria: {
        es_valida:
          !errorConsulta,

        error_consulta:
          errorConsulta,

        total_eventos:
          eventosOcupados.length
      },

      eventosOcupadosPeluqueria:
        eventosOcupados
    }
  }
];

const DateTime =
