    : [];

const zonaHoraria =
  String(
    busqueda.zona_horaria ||
    config.zona_horaria ||
    "America/Santiago"
  ).trim();

const diasABuscar =
  Math.max(
    Number(
      busqueda.dias_a_buscar ||
      config.dias_a_buscar ||
      7
    ),
    1
  );

const cantidadAlternativas =
  Math.max(
    Number(
      busqueda.cantidad_alternativas ||
      config.cantidad_alternativas ||
      3
    ),
    1
  );

const duracionMinutos =
  Number(
    busqueda.duracion_minutos ||
    0
  );

const intervaloInicioMinutos =
  Math.max(
    Number(
      busqueda.intervalo_inicio_minutos ||
      config.intervalo_inicio_predeterminado_minutos ||
      config.intervalo_inicio_minutos_default ||
      config.intervalo_inicio_minutos ||
      30
    ),
    1
  );

const ahora =
  $now.setZone(
    zonaHoraria
  );

const inicioSolicitado =
  busqueda.inicio_solicitado
    ? DateTime.fromISO(
        busqueda.inicio_solicitado,
        {
          zone: zonaHoraria
        }
      )
    : null;

// --------------------------------------------------
// Horarios configurados
// --------------------------------------------------

const normalizarTexto = (
  valor
) =>
  String(valor || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(
      /[\u0300-\u036f]/g,
      ""
    )
    .trim();

const nombresDias = {
  1: "lunes",
  2: "martes",
  3: "miercoles",
  4: "jueves",
  5: "viernes",
  6: "sabado",
  7: "domingo"
};

const horariosPorDia =
  config.horarios_por_dia ||
  config.horarios ||
  config.schedule ||
  {};

const buscarConfiguracionDia = (
  nombreDia
) => {
  if (
    !horariosPorDia ||
    typeof horariosPorDia !== "object"
  ) {
    return null;
  }

  for (
    const [clave, valor]
    of Object.entries(
      horariosPorDia
    )
  ) {
    if (
      normalizarTexto(clave) ===
      nombreDia
    ) {
      return valor;
    }
  }

  return null;
};

const normalizarVentanas = (
  valor
) => {
  if (
    valor === null ||
    valor === undefined ||
    valor === false
  ) {
    return [];
  }

  if (typeof valor === "string") {
    const coincidencia =
      valor.match(
        /(\d{1,2}:\d{2})\s*[-–]\s*(\d{1,2}:\d{2})/
      );

    return coincidencia
      ? [
          {
            apertura:
              coincidencia[1],

            cierre:
              coincidencia[2]
          }
        ]
      : [];
  }

  if (Array.isArray(valor)) {
    return valor.flatMap(
      (item) =>
        normalizarVentanas(item)
    );
  }

  if (typeof valor === "object") {
    const activo =
      valor.activo ??
      valor.active ??
      valor.habilitado ??
      true;

    if (activo === false) {
      return [];
    }

    const apertura =
      valor.apertura ||
      valor.inicio ||
      valor.desde ||
      valor.start ||
      valor.hora_inicio ||
      "";

    const cierre =
      valor.cierre ||
      valor.fin ||
      valor.hasta ||
      valor.end ||
      valor.hora_fin ||
      "";

    if (
      apertura &&
      cierre
    ) {
      return [
        {
          apertura:
            String(
              apertura
            ).trim(),

          cierre:
            String(
              cierre
            ).trim()
        }
      ];
    }

    return normalizarVentanas(
      valor.ventanas ||
      valor.bloques ||
      valor.rangos ||
      valor.windows ||
      []
    );
  }

  return [];
};

// --------------------------------------------------
// Utilidades
// --------------------------------------------------

const convertirHoraAMinutos = (
  valor
) => {
  const coincidencia =
    String(valor || "")
      .trim()
      .match(
        /^(\d{1,2}):(\d{2})$/
      );

  if (!coincidencia) {
    return null;
  }

  const horas =
    Number(coincidencia[1]);

  const minutos =
    Number(coincidencia[2]);

  if (
    horas < 0 ||
    horas > 23 ||
    minutos < 0 ||
    minutos > 59
  ) {
    return null;
  }

  return (
    horas * 60 +
    minutos
  );
};

const fechasBloqueadasConfiguradas =
  config.fechas_bloqueadas ||
  config.blocked_dates ||
  [];

const fechasBloqueadas =
  new Set(
    (
      Array.isArray(
        fechasBloqueadasConfiguradas
      )
        ? fechasBloqueadasConfiguradas
        : []
    )
      .map((item) => {
        if (
          typeof item === "string"
        ) {
          return item.trim();
        }

        return String(
          item?.fecha ||
          item?.date ||
          ""
        ).trim();
      })
      .filter(Boolean)
  );

const eventosNormalizados =
  eventos
    .map((evento) => {
      const inicio =
        DateTime.fromISO(
          evento.inicio,
          {
            zone: zonaHoraria
          }
        );

      const fin =
        DateTime.fromISO(
          evento.fin,
          {
            zone: zonaHoraria
          }
        );

      return {
        inicio,
        fin
      };
    })
    .filter(
      (evento) =>
        evento.inicio.isValid &&
        evento.fin.isValid
    );

const seSuperpone = (
  inicio,
  fin
) =>
  eventosNormalizados.some(
    (evento) =>
      inicio < evento.fin &&
      fin > evento.inicio
  );

// --------------------------------------------------
// Generar candidatos
// --------------------------------------------------

const candidatos = [];

const fechaInicial =
  ahora.startOf("day");

if (duracionMinutos > 0) {
  for (
    let desplazamiento = 0;
    desplazamiento < diasABuscar;
    desplazamiento++
  ) {
    const fecha =
      fechaInicial.plus({
        days: desplazamiento
      });

    const fechaIso =
      fecha.toISODate();

    if (
      fechasBloqueadas.has(
        fechaIso
      )
    ) {
      continue;
    }

    const nombreDia =
      nombresDias[fecha.weekday];

    const ventanas =
      normalizarVentanas(
        buscarConfiguracionDia(
          nombreDia
        )
      );

    for (
      const ventana
      of ventanas
    ) {
      const apertura =
        convertirHoraAMinutos(
          ventana.apertura
        );

      const cierre =
        convertirHoraAMinutos(
          ventana.cierre
        );

      if (
        apertura === null ||
        cierre === null ||
        cierre <= apertura
      ) {
        continue;
      }

      for (
        let minutoInicio =
          apertura;
        minutoInicio +
          duracionMinutos <=
          cierre;
        minutoInicio +=
          intervaloInicioMinutos
      ) {
        const hora =
          Math.floor(
            minutoInicio / 60
          );

        const minuto =
          minutoInicio % 60;

        const inicio =
          fecha.set({
            hour: hora,
            minute: minuto,
            second: 0,
            millisecond: 0
          });

        const fin =
          inicio.plus({
            minutes:
              duracionMinutos
          });

        if (
          inicio <= ahora
        ) {
          continue;
        }

        if (
          inicioSolicitado?.isValid &&
          inicio.toMillis() ===
            inicioSolicitado.toMillis()
        ) {
          continue;
        }

        if (
          seSuperpone(
            inicio,
            fin
          )
        ) {
          continue;
        }

        candidatos.push({
          inicio,
          fin
        });
      }
    }
  }
}

// --------------------------------------------------
// Ordenar por cercanía al horario solicitado
// --------------------------------------------------

const referencia =
  inicioSolicitado?.isValid
    ? inicioSolicitado
    : ahora;

candidatos.sort(
  (a, b) => {
    const distanciaA =
      Math.abs(
        a.inicio.toMillis() -
        referencia.toMillis()
      );

    const distanciaB =
      Math.abs(
        b.inicio.toMillis() -
        referencia.toMillis()
      );

    if (
      distanciaA !== distanciaB
    ) {
      return (
        distanciaA -
        distanciaB
      );
    }

    return (
      a.inicio.toMillis() -
      b.inicio.toMillis()
    );
  }
);

