assignments.value:
={{ (() => {
  const origen =
    $("Preparar estado peluquería confirmado")
      .first()
      .json;

  const cita =
    origen.citaPeluqueria || {};

  const zonaHoraria =
    String(
      cita.zona_horaria ||
      "America/Santiago"
    ).trim();

  const inicioTexto =
    String(
      cita.start_time || ""
    ).trim();

  const inicio =
    inicioTexto
      ? DateTime.fromISO(
          inicioTexto,
          {
            zone: zonaHoraria
          }
        )
      : null;

  const fechaTexto =
    inicio &&
    inicio.isValid
      ? inicio
          .setLocale("es")
          .toFormat(
            "cccc d 'de' LLLL 'a las' HH:mm"
          )
      : "";

  const servicio =
    String(
      cita.nombre_servicio ||
      "peluquería"
    ).trim();

  const mascota =
    String(
      cita.nombre_mascota ||
      "tu mascota"
    ).trim();

  const duracion =
    Number(
      cita.duracion_minutos || 0
    );

  let respuesta =
    `La cita de ${servicio} para ${mascota} quedó confirmada`;

  if (fechaTexto) {
    respuesta +=
      ` para el ${fechaTexto}`;
  }

  if (duracion > 0) {
    respuesta +=
      `. La duración estimada es de ${duracion} minutos.`;
  } else {
    respuesta += ".";
  }

  return respuesta;
})() }}
